[6162] = { en = "A Husband's Last Battle", tier = 4,
  t = "Het laatste gevecht van een echtgenoot",
  d = "Mijn man reisde door Felwood voor de eer van onze clan. Hij vocht tegen de Shadow Council en andere verdorven gruwelen!$B$BHij ontsnapte vaak aan de dood. Toen kreeg ik een brief van hem. Hij schreef dat een druïde hem om hulp had gevraagd tegen een grote, bezoedelde furbolg: Overlord Ror. Daarna heeft niemand ooit nog iets van de twee gehoord.$B$BIk wil de klauwhand van die Ror, $N. Hij moet ervoor boeten dat hij me weduwe heeft gemaakt! Ik denk dat het wezen in het zuiden is... dicht bij de grens met Ashenvale.",
  o = "Dood Overlord Ror en breng zijn klauw naar Dreka'Sur bij Bloodvenom Post in Felwood.",
  p = "Heb je de kop van het beest al, $N? Het zal boeten voor zijn misdaden. Het kan me niet schelen of hij verdorven is of gewoon boos omdat hij in zo'n somber bos leeft. Geen furbolg die zulke misdaden tegen mijn familie pleegt, blijft lang leven!",
  c = "Je brengt me eer omdat je je woord hebt gehouden. Mijn man stierf in de strijd. Daar zou hij trots op zijn geweest. Maar ik kon niet rusten tot ik wist dat het wezen dat me dwong om alleen verder te leven, had betaald voor wat het had gedaan.$b$bNogmaals bedankt, $N.",
  g = { {"echtgenoot", "husband"}, {"verdorven", "corrupt (verdorven)"}, {"gruwelen", "atrocities, horrors (gruwel)"}, {"ontsnapte", "escaped (ontsnappen)"}, {"bezoedelde", "befouled, defiled (bezoedeld)"}, {"klauwhand", "clawed hand"}, {"boeten", "to pay (for a crime), to atone"}, {"weduwe", "widow"}, {"grens", "border"}, {"misdaden", "crimes (misdaad)"}, {"somber", "dismal, gloomy"}, {"pleegt", "commits (plegen)"}, {"je woord gehouden", "kept your word"}, {"dwong", "forced (dwingen)"} },
},

[4505] = { en = "Well of Corruption", tier = 4,
  t = "Bron van verdorvenheid",
  d = "Sommigen zeggen misschien dat ik bijzonder wreed ben... Maar eigenlijk wil ik alleen heel graag dat de Horde op elke mogelijke manier voordeel krijgt tegenover de Alliance.$B$BMijn nieuwste interesse is een maanbron bij de Ruins of Constellas, ten zuiden van hier. De Jadefire-saters zorgen ervoor. De maanbron was ooit een symbool van vernieuwing voor die onuitstaanbare nachtelfen. Nu is hij verdorven en wordt hij gebruikt om meer saters voort te brengen.$B$BIk heb een idee, $N, en ik wil graag een monster van het water... voor mijn kleine katachtige vriendje hier.",
  o = "Verzamel een monster van het verdorven water uit de maanbron van de Jadefire Satyrs en breng het naar Winna Hazzard bij Bloodvenom Post.",
  p = "Dit is van het grootste belang. Ga nu maar op weg.",
  c = "Heel goed. We moeten een manier vinden om deze verdorvenheid tegen onze vijanden te gebruiken...",
  g = { {"bron", "well, spring"}, {"verdorvenheid", "corruption"}, {"bijzonder", "exceptionally, particularly"}, {"wreed", "cruel"}, {"voordeel", "advantage"}, {"maanbron", "moonwell"}, {"saters", "satyrs (sater)"}, {"vernieuwing", "renewal"}, {"onuitstaanbare", "insufferable (onuitstaanbaar)"}, {"voort te brengen", "to bring forth, to produce (voortbrengen)"}, {"katachtige", "feline (katachtig)"}, {"van het grootste belang", "of the utmost importance"} },
},

[4506] = { en = "Corrupted Sabers", tier = 4,
  t = "Verdorven sabelkatten",
  d = "Dit verdorven water kunnen we in ons voordeel gebruiken, $N. Met maar een klein beetje van het water werd mijn katje twee keer zo groot, en het lijkt ook sterker... op de een of andere manier. Deze katten kunnen nog nuttig blijken...$B$BHier, $N. Neem deze kattenmand en laat het katje erin vrij naast de maanbron bij de Ruins of Constellas. He, he... Je zult vast blij zijn met het resultaat!$B$BBreng de kat terug naar mij, dan zorg ik dat het de moeite waard is.",
  o = "Breng Winna's katje naar de verdorven maanbron, laat het vrij en breng het dan terug naar Winna.$B$BAls je terug bent bij Winna, klik je op de kat om hem aan Winna te geven.",
  p = "Zeg me niet dat je daar niet terug kunt gaan! Schiet op!",
  c = "Uitstekend!$b$bDe Forsaken zullen elk middel gebruiken om de Alliance te verpletteren! Het verdorven water zal ons zeker helpen bij ons toekomstige werk...",
  e = "Breng de verdorven kat terug naar Winna Hazzard",
  g = { {"sabelkatten", "sabers, sabercats (sabelkat)"}, {"in ons voordeel", "to our advantage"}, {"op de een of andere manier", "somehow"}, {"nuttig blijken", "prove useful"}, {"kattenmand", "cat carrier"}, {"laat vrij", "release (vrijlaten)"}, {"de moeite waard", "worth it, worth your time"}, {"elk middel", "any means"}, {"verpletteren", "to crush"}, {"toekomstige", "future (toekomstig)"} },
},

[5232] = { en = "Return to the Bulwark", tier = 4,
  t = "Terug naar The Bulwark",
  d = "Voorzichtig vul je de fles met genoeg vocht uit de ketel voor wat jij een monster van de juiste grootte vindt.$B$BNu je het gif hebt, is het tijd om terug te gaan naar Shadow Priestess Vandis bij The Bulwark om de missie af te ronden.",
  o = "Breng de Filled Dalson's Tears Bottle naar Shadow Priestess Vandis bij The Bulwark, Western Plaguelands.",
  p = "We weten dat elke ketel een andere mix van ingrediënten gebruikt om zijn gif te maken, het gif dat de pest veroorzaakt. We weten ook dat we voor elke ketel een eigen tegenmiddel moeten ontwikkelen. Jouw monster van Dalson's Tears wordt de sleutel om te ontdekken welke ingrediënten precies nodig zijn voor die ketel.",
  c = "Ah, hier zit genoeg in om te onderzoeken. Goed gedaan, $N!$b$bDe volgende stap ligt voorlopig bij ons. We moeten een lijst maken van ingrediënten die, samen met wat er al in de ketel zit, als tegenmiddel werken.$b$bDe enige manier om dit erin te krijgen, is door de ingrediënten direct in de ketel te doen. Apothecary Dithers weet daar meer over, dus praat zo snel mogelijk met hem.",
  g = { {"vocht", "liquid, fluid"}, {"ketel", "cauldron"}, {"monster", "sample (also: monster)"}, {"gif", "poison"}, {"ingrediënten", "ingredients, reagents (ingrediënt)"}, {"veroorzaakt", "causes (veroorzaken)"}, {"tegenmiddel", "counter agent, antidote"}, {"ontwikkelen", "to develop"}, {"onderzoeken", "to study, to research"}, {"voorlopig", "for now"}, {"af te ronden", "to complete (afronden)"} },
},

[5233] = { en = "Target: Writhing Haunt", tier = 4,
  t = "Doelwit: Writhing Haunt",
  d = "Twee ketels zijn met succes geopend. Je kunt er altijd bij blijven komen, maar we willen ook de andere twee nog openen. Dan hebben we allemaal meer mogelijkheden om het tegenmiddel toe te voegen!$B$BDeze keer ga je naar de ketel van de Writhing Haunt. Die ligt bijna recht ten oosten van Andorhal, vrij dicht bij de vervallen stadsmuren. Versla ook hier de Cauldron Lord die er is, voor zijn sleutel. Gebruik deze fles om het monster uit de ketel te halen.$B$BSucces met de jacht, $N!",
  o = "Ga naar de Writhing Haunt in Western Plaguelands. Zoek en versla de Cauldron Lord daar en gebruik zijn sleutel om bij de ketel te komen. Je moet de Empty Writhing Haunt Bottle bij je hebben om een monster te nemen van de giffen in de ketel.",
  p = "Een toegangsluik van de ketel zit nog stevig dicht. Om het te openen, moet je de sleutel vinden.",
  c = "De sleutel van de Cauldron Lord opent het toegangsluik van deze ketel en verdwijnt dan, net als de sleutels bij de vorige ketels. Onder het platform van de ketel kolkt heftig een stof die naar rotting ruikt.$b$bEr is een kleine kraan waar de fles goed genoeg onder past. Zo kun je een monster nemen voor Shadow Priestess Vandis, terug bij The Bulwark.",
  g = { {"doelwit", "target"}, {"mogelijkheden", "options, possibilities (mogelijkheid)"}, {"toe te voegen", "to add (toevoegen)"}, {"recht ten oosten", "due east"}, {"vervallen", "ruined, dilapidated"}, {"stadsmuren", "city walls (stadsmuur)"}, {"giffen", "poisons (gif)"}, {"toegangsluik", "access panel, access hatch"}, {"stevig", "firmly"}, {"kolkt", "churns, swirls (kolken)"}, {"heftig", "violently"}, {"rotting", "rot, decay"}, {"kraan", "tap, spigot"} },
},

[5402] = { en = "Minion's Scourgestones", tier = 4,
  t = "Minion's Scourgestones",
  p = "Een Minion's Scourgestone is het insigne van het gewone voetvolk van de Scourge. Je vindt ze soms bij de zwakkere troepen in de Plaguelands, al moet je 'zwakker' natuurlijk wel in verhouding zien. Waar de Scourge ook is, je mag ze nooit onderschatten.$B$BDe Argent Dawn geeft op dit moment een valor token in ruil voor twintig van deze insignes. Die ruil doe ik graag, als je genoeg Scourgestones hebt verdiend!",
  c = "Gefeliciteerd, $N. Met plezier geef ik je een Argent Dawn valor token!$B$BDe tokens hebben twee doelen. Eén: je kunt ze gebruiken om je positie bij de Argent Dawn te verbeteren. Zo krijg je misschien toegang tot keuzes en beloningen die we bewaren voor onze geëerde en hooggeachte bondgenoten. Twee: je kunt ze, samen met geld, aan onze kwartiermeesters geven als betaling voor enkele van de waardevolste spullen van de Dawn.$B$BWat je ook kiest, weet dat je je aanstelling verdient. Goed gedaan!",
  g = { {"insigne", "insignia, badge"}, {"voetvolk", "rank and file, foot soldiers"}, {"in verhouding", "in context, relatively"}, {"onderschatten", "to underestimate"}, {"in ruil voor", "in exchange for"}, {"geëerde", "honored (geëerd)"}, {"hooggeachte", "revered, highly respected (hooggeacht)"}, {"bondgenoten", "allies (bondgenoot)"}, {"kwartiermeesters", "quartermasters (kwartiermeester)"}, {"waardevolste", "most valuable (waardevol)"}, {"aanstelling", "commission, appointment"} },
},

[5403] = { en = "Invader's Scourgestones", tier = 4,
  t = "Invader's Scourgestones",
  p = "Een Invader's Scourgestone is het insigne van de elitetroepen van de Scourge. Je vindt ze soms bij de sterkere troepen in de Plaguelands. Zo'n wezen doden is echt een uitdaging, maar wel een die je met plezier moet aangaan als je de opdracht hebt om het kwaad te verslaan.$B$BDe Argent Dawn geeft op dit moment een valor token in ruil voor tien van deze insignes. Breng ze hier naar mij, dan zorg ik dat je je verdiende beloning krijgt.",
  c = "Gefeliciteerd, $N. Met plezier geef ik je een Argent Dawn valor token!$B$BElke valor token die we geven aan iemand die het verdient, is een teken dat het tij keert tegen de Scourge. Steeds meer helden vechten tegen de Scourge in hun eigen landen. Daarom zal de Argent Dawn zeker vooraan staan als het tijd is om oorlog te voeren tegen het grootste kwaad van de Scourge. Ik hoop dat de moed die je nodig had om je token te krijgen, je dan ook de overwinning zal brengen!",
  g = { {"insigne", "insignia, badge"}, {"elitetroepen", "elite troops"}, {"uitdaging", "challenge"}, {"aangaan", "to take on"}, {"het kwaad", "evil"}, {"verdiende", "deserved, earned (verdiend)"}, {"het tij keert", "the tide is turning (keren)"}, {"vooraan staan", "to be at the forefront"}, {"oorlog te voeren", "to wage war (oorlog voeren)"}, {"moed", "courage, valor"}, {"overwinning", "victory"} },
},

[5405] = { en = "Argent Dawn Commission", tier = 4,
  t = "De aanstelling van de Argent Dawn",
  c = "Iedereen die namens de Argent Dawn tegen het kwaad vecht, moet onze aanstelling dragen. Daarmee krijg je het recht op de beloningen die onze kwartiermeesters te bieden hebben.$B$BZolang je de aanstelling hebt, kun je Scourgestones krijgen van verslagen Scourge. Dat zijn insignes die ze soms bij zich hebben. Verzamel deze insignes en breng ze naar mij. Voor elke set die je inlevert, krijg je ons teken van heldenmoed: de Argent Dawn Valor Token.$B$BVervul je lot, $c. Doe vandaag nog mee aan de strijd!",
  g = { {"aanstelling", "commission, appointment"}, {"namens", "on behalf of"}, {"het recht op", "the right to"}, {"kwartiermeesters", "quartermasters (kwartiermeester)"}, {"insignes", "insignia (insigne)"}, {"inlevert", "turn in, hand in (inleveren)"}, {"heldenmoed", "heroism"}, {"vervul", "fulfil (vervullen)"}, {"lot", "destiny, fate"} },
},

[5406] = { en = "Corruptor's Scourgestones", tier = 4,
  t = "Corruptor's Scourgestones",
  p = "Een Corruptor's Scourgestone is het insigne van de opperheren van de Scourge. Een machtig wezen dat gezag heeft over de Scourge, heeft er altijd een. Zo'n kwaadaardig wezen doden helpt zeker de zaak van de Argent Dawn, en elke goede zaak!$B$BNamens de Argent Dawn geef ik je een valor token in ruil voor maar één van deze insignes. Wees voorzichtig als je er een probeert te krijgen, $N. Met zulke machtige wezens valt niet te spotten.",
  c = "Gefeliciteerd, $N. Met plezier geef ik je een Argent Dawn valor token!$B$BAls je op deze manier een valor token krijgt, laat dat zien dat je een echte held bent in de strijd voor het goede. We waarderen elke inspanning tegen de Scourge, maar wie een van hun leiders verslaat, bezorgt ze echt een verpletterende nederlaag!$B$BVoor de Dawn, mijn $gbroeder:zuster;!",
  g = { {"opperheren", "overlords (opperheer)"}, {"gezag", "authority"}, {"kwaadaardig", "malevolent, evil"}, {"de zaak", "the cause"}, {"valt niet te spotten", "is not to be trifled with (spotten)"}, {"waarderen", "to value, to appreciate"}, {"inspanning", "effort"}, {"bezorgt", "gives, delivers (bezorgen)"}, {"verpletterende", "crushing (verpletterend)"}, {"nederlaag", "defeat"} },
},

[6390] = { en = "A Plague Upon Thee", tier = 4,
  t = "Een plaag over jou",
  d = "Je kijkt rond in de houtzagerij naar iets waarmee je het vat open kunt maken. Je vindt een koevoet die geschikt lijkt.$B$BJe zet je voeten stevig neer en bidt dat je de zagerij uit kunt komen voordat de termieten bij je zijn.",
  o = "Laat de Plagueland Termites los in de Northridge Lumber Mill. Ga daarna met het Barrel of Plagueland Termites terug naar Mickey Levine bij The Bulwark in Tirisfal Glades.",
  p = "Is het gelukt, $N? Heb je de termieten in de houtzagerij losgelaten?$B$BHet was al erg genoeg dat mijn familie hun werk en hun leven verloor. Maar toen zag ik ook nog dat de plek waar ik mijn jeugd heb doorgebracht, werd overgenomen door die walgelijke zogenaamde heilige mannen... bah!!",
  c = "Dank je, $N. Hier, neem dit geld. Het spijt me dat het niet meer is, maar probeer er plezier in te hebben dat je de plannen van de Scarlet Crusade hebt helpen vernietigen!",
  g = { {"plaag", "plague"}, {"houtzagerij", "lumber mill"}, {"vat", "barrel"}, {"koevoet", "crowbar"}, {"geschikt", "suitable"}, {"bidt", "pray (bidden)"}, {"termieten", "termites (termiet)"}, {"losgelaten", "released (loslaten)"}, {"jeugd", "childhood, youth"}, {"walgelijke", "disgusting (walgelijk)"}, {"zogenaamde", "so-called (zogenaamd)"}, {"vernietigen", "to destroy"} },
},

[4987] = { en = "Glyphed Oaken Branch", tier = 4,
  t = "Glyphed Oaken Branch",
  d = "De levenloze hand van de tauren-druïde houdt een eikenhouten tak vast die verrassend gezond lijkt. Als je de tak bekijkt, zie je druïdische tekens die in de schors zijn gekerfd.$B$BAls je de tak vastpakt, merk je dat hij warm aanvoelt, warmer dan zou moeten. Het beeld van Thunder Bluff in Mulgore komt in je gedachten, Elder Rise om precies te zijn. En de woorden 'Cenarion Circle' liggen op het puntje van je tong. Het lijkt erop dat in de tak zelf is gelegd waar je hem heen moet brengen.",
  o = "Volgens de magie in de Glyphed Oaken Branch wilde de tauren-druïde dat de tak naar de Cenarion Circle in Thunder Bluff ging. Dat is de volgende stap. Vraag een van de druïden daar om hulp.",
  p = "Namens de Cenarion Circle heet ik je welkom in deze enclave, $C. Wat kom je hier doen?",
  c = "Dit komt van Mulgris, zeg je? We hadden gehoord dat hij de wezens wilde helpen die lijden in de Plaguelands, maar dit is heel onverwacht... en heel verdrietig. Mulgris is... was een goede vriend. Ik zal diep om zijn dood rouwen.$B$BDankzij jouw ijver is zijn werk niet voor niets geweest. In deze tak is veel kennis opgeslagen over de pest die de Scourge over het land verspreidt. We zullen hem zorgvuldig bestuderen. En jij: neem dit alsjeblieft aan. Het is het minste wat we kunnen doen voor je edele inzet.",
  g = { {"levenloze", "lifeless (levenloos)"}, {"eikenhouten", "oaken, made of oak"}, {"verrassend", "surprisingly"}, {"druïdische", "druidic (druïdisch)"}, {"schors", "bark"}, {"gekerfd", "carved (kerven)"}, {"aanvoelt", "feels (aanvoelen)"}, {"op het puntje van je tong", "on the tip of your tongue"}, {"enclave", "enclave"}, {"lijden", "to suffer"}, {"rouwen", "to mourn"}, {"ijver", "diligence, zeal"}, {"verspreidt", "spreads (verspreiden)"}, {"zorgvuldig", "carefully"}, {"inzet", "effort, commitment"} },
},

[5098] = { en = "All Along the Watchtowers", tier = 4,
  t = "Langs alle wachttorens",
  d = "Met een magisch voorwerp, een Beacon Torch, kunnen we doelen markeren die we zelf kiezen, zodat onze troepen er later iets mee kunnen doen. Daarvoor willen we het nu gebruiken, want we denken dat de Scourge de wachttorens van Andorhal gebruikt om de bewegingen van hun troepen te sturen.$B$BJouw missie: breek door de verdediging van Andorhal en plaats bakens bij alle vier de wachttorens. Je moet in de deuropening van elke toren staan om het baken te plaatsen. Daarna markeert het de toren. Er zitten maar vijf ladingen in de Beacon Torch, dus gebruik ze verstandig!",
  o = "Gebruik de Beacon Torch om elke toren in Andorhal te markeren. Je moet in de deuropening van de toren staan om hem te markeren.$B$BAls alle vier de torens gemarkeerd zijn, breng je de Beacon Torch terug naar High Executor Derrington bij The Bulwark, Western Plaguelands.",
  p = "Als de torens gemarkeerd zijn, worden ze de belangrijkste doelen voor onze aanval op Andorhal. Ik vermoed dat het grootste gevaar van Andorhal tevoorschijn komt zodra we de torens uitschakelen. Vanaf dan wordt het een open gevecht om de stad!$b$bJe komt melden dat het gelukt is, toch? Vergeet de Beacon Torch niet. We moeten ons materieel onder controle houden.",
  c = "Mijn heksenmeesters melden dat onze bakenzoekers heel sterke signalen opvangen bij alle vier de torens! Je hebt mijn bevelen uitgevoerd met de vaardigheid en precisie van een ervaren veteraan. Je dienst aan de Horde wordt opnieuw genoteerd, $N!$B$BNu de torens gemarkeerd zijn, zijn onze voorbereidingen voor de aanval klaar. Het is tijd om de strijd naar de Scourge te brengen!",
  o1 = "Toren één gemarkeerd",
  o2 = "Toren twee gemarkeerd",
  o3 = "Toren drie gemarkeerd",
  o4 = "Toren vier gemarkeerd",
  g = { {"wachttorens", "watchtowers (wachttoren)"}, {"markeren", "to mark"}, {"bakens", "beacons (baken)"}, {"deuropening", "doorway"}, {"ladingen", "charges (lading)"}, {"verstandig", "wisely"}, {"vermoed", "suspect (vermoeden)"}, {"tevoorschijn komt", "emerges, appears (tevoorschijn komen)"}, {"uitschakelen", "to neutralize, to switch off"}, {"materieel", "materiel, equipment"}, {"heksenmeesters", "warlocks (heksenmeester)"}, {"opvangen", "to pick up (signals)"}, {"bevelen", "orders (bevel)"}, {"genoteerd", "noted (noteren)"}, {"voorbereidingen", "preparations (voorbereiding)"} },
},

[964] = { en = "Skeletal Fragments", tier = 4,
  t = "Skeletal Fragments",
  d = "De sleutel tot Scholomance heet een Skeleton Key. Hij moet gesmeed worden uit de resten van een skelet, eigenlijk van meerdere skeletten. Daarna moet hij in een goede mal gehard worden met alleen de sterkste metalen. Een machtszegel van een wezen dat van nature het portaal naar Scholomance kan openen, laat de sleutel uiteindelijk werken.$B$BMaar laten we bij het begin beginnen, $N. We hebben skeletfragmenten nodig om de sleutel te smeden. De skeletten in Andorhal moeten ons geven wat we nodig hebben, maar die buiten de muren zijn misschien ook goed.",
  o = "Breng 15 Skeletal Fragments naar Apothecary Dithers bij The Bulwark, Western Plaguelands.",
  p = "Dood er veel, en vaak, $C. We hebben een flinke voorraad bruikbare skeletfragmenten nodig voor de buitenlaag van de sleutel. Ze noemen het niet voor niets een Skeleton Key, weet je.",
  c = "Dit is goed, $N! Nu is het mijn beurt. Ik behandel ze zo dat ze hard genoeg worden om het zware smeedproces te overleven dat ze later krijgen.$b$bDe volgende stap is een geschikte mal voor de sleutel. Ik ken een goblin-smid in Tanaris die vroeger mallen heeft gemaakt voor vergelijkbare macabere voorwerpen. Hij werkt voor wie goblins meestal voor werken: wie het meeste biedt.",
  g = { {"gesmeed", "forged (smeden)"}, {"resten", "remains (rest)"}, {"skelet", "skeleton"}, {"mal", "mold"}, {"gehard", "hardened (harden)"}, {"machtszegel", "signet of power"}, {"van nature", "naturally, by nature"}, {"uiteindelijk", "in the end, ultimately"}, {"voorraad", "supply, stock"}, {"bruikbare", "usable (bruikbaar)"}, {"buitenlaag", "outer layer"}, {"niet voor niets", "not for nothing"}, {"smeedproces", "forging process"}, {"vergelijkbare", "similar (vergelijkbaar)"}, {"macabere", "macabre (macaber)"} },
},

[5514] = { en = "Mold Rhymes With...", tier = 4,
  t = "Mal rijmt op...",
  d = "De goblin met wie je moet praten, is Krinkle Goodsteel. Hij verkoopt zijn vaardigheden aan wie het meeste biedt, in Gadgetzan, in de woestijn van Tanaris. Hij is waarschijnlijk de enige die de mal kan maken die we nodig hebben, en zijn diensten zijn niet goedkoop. We vragen je nu om diep in je buidel te tasten en zijn prijs te betalen, wat die ook is.$B$BIk ben een apotheker, geen bankier. Als ik goud had liggen, zat ik hier echt niet.$B$BIk heb geloof ik weer hardop gezegd wat ik voor me had moeten houden. Oeps.$B$BGadgetzan wacht op je! Succes!",
  o = "Breng de Imbued Skeletal Fragments en 15 goudstukken naar Krinkle Goodsteel in Gadgetzan.",
  p = "Ja, ik weet wie je bent, en ik weet waarom je hier bent. Dithers heeft me een bericht gestuurd voordat je kwam. Laten we meteen ter zake komen, goed?$b$bIk heb een mal die je kunt gebruiken voor de skeleton key, maar die gaat je wat kosten: vijftien goud, vooraf, zonder onderhandelen. Ik doe de skeletfragmenten voor je in de mal. En ik leer je ook hoe je de schacht van de sleutel smeedt zonder dat je iets van smeden weet... en dat allemaal gratis.$b$bWie zegt dat huurlingen geen scherpe prijzen hebben!",
  c = "Dithers zei dat je zou leveren, en dat heb je gedaan! Afspraak is afspraak. Ik doe de fragmenten voor je in de mal.$b$bHeeft Dithers ze al behandeld? Uitstekend... anders had je een lange reis terug naar The Bulwark moeten maken.",
  g = { {"rijmt op", "rhymes with (rijmen)"}, {"vaardigheden", "skills (vaardigheid)"}, {"diensten", "services (dienst)"}, {"diep in je buidel tasten", "to dig deep into your pocket"}, {"apotheker", "apothecary"}, {"hardop", "out loud"}, {"ter zake komen", "to get to the point"}, {"vooraf", "up front, in advance"}, {"onderhandelen", "to negotiate"}, {"schacht", "shaft, stem"}, {"huurlingen", "mercenaries (huurling)"}, {"scherpe prijzen", "competitive prices"}, {"afspraak is afspraak", "a deal is a deal"} },
},

[5235] = { en = "Target: Gahrron's Withering", tier = 4,
  t = "Doelwit: Gahrron's Withering",
  d = "De laatste ketel die nog over is, staat op een boerderij die nu Gahrron's Withering heet. Hij wordt bewaakt door enkele van de sterkere dienaren van de Scourge, namelijk schimmen en geesten. Daar valt niet mee te spotten, $N.$B$BGahrron's Withering ligt ver ten oosten van The Bulwark, dicht bij de plek waar de Eastern Plaguelands beginnen. Versla ook hier de Cauldron Lord die er is, voor zijn sleutel. Hier is je lege fles voor het monster. Breng hem gevuld bij me terug. Mogen de schaduwen je beschermen tijdens deze gevaarlijke missie, $c.",
  o = "Ga naar Gahrron's Withering in Western Plaguelands. Zoek en versla de Cauldron Lord daar en gebruik zijn sleutel om bij de ketel te komen. Je moet de Empty Gahrron's Withering Bottle bij je hebben om een monster te nemen van de giffen in de ketel.",
  p = "Een toegangsluik van de ketel zit nog stevig dicht. Om het te openen, moet je de sleutel vinden.",
  c = "De sleutel van Cauldron Lord Soulwrath valt uit elkaar zodra hij het slot raakt van het toegangsluik onder aan het platform van de ketel. Binnen hoor je zacht gerammel, en het luik zwaait open. Je ziet nog meer stroperige giffen in het binnenwerk van de ketel.$b$bEr is een kleine kraan waar de fles goed genoeg onder past. Zo kun je een monster nemen voor Shadow Priestess Vandis, terug bij The Bulwark.",
  g = { {"bewaakt", "guarded (bewaken)"}, {"dienaren", "minions, servants (dienaar)"}, {"schimmen", "wraiths, shades (schim)"}, {"daar valt niet mee te spotten", "they are not to be trifled with"}, {"gevuld", "filled (vullen)"}, {"valt uit elkaar", "falls apart, disintegrates (uit elkaar vallen)"}, {"gerammel", "clanking, rattling"}, {"zwaait open", "swings open (openzwaaien)"}, {"stroperige", "viscous, syrupy (stroperig)"}, {"binnenwerk", "inner workings, framework"}, {"toegangsluik", "access panel, access hatch"}, {"kraan", "tap, spigot"} },
},

[5236] = { en = "Return to the Bulwark", tier = 4,
  t = "Terug naar The Bulwark",
  d = "Voorzichtig draai je de kraan in het bedieningspaneel dicht, terwijl je kijkt hoe het smerige vocht van de ketel in de lege fles druppelt.$B$BNu je het gif hebt, is het tijd om terug te gaan naar Shadow Priestess Vandis bij The Bulwark om de missie af te ronden.",
  o = "Breng de Filled Gahrron's Withering Bottle naar Shadow Priestess Vandis bij The Bulwark, Western Plaguelands.",
  p = "In Gahrron's Withering staat de laatste ketel waar we hier in het westen toegang toe moeten krijgen. Zodra we een monster van de pest uit die ketel hebben, kunnen we onze ingrediënten via vier verschillende ketels in de omgeving brengen! De Scourge zal het heel moeilijk krijgen om ons uit alle vier weg te houden, zelfs met de macht van Kel'Thuzad achter zich.",
  c = "Gefeliciteerd, $N, je hebt de laatste ketel voor ons geopend! Apothecary Dithers weet binnenkort welke ingrediënten deze ketel nodig heeft voor het mengsel.$b$bEn jij: ik weet zeker dat High Executor Derrington je persoonlijk wil bedanken voor je hulp. Zonder jou was onze strijd tegen de Scourge bijna onmogelijk geweest. Ik dank je, machtige $C.",
  g = { {"bedieningspaneel", "control panel"}, {"smerige", "filthy, putrid (smerig)"}, {"druppelt", "drips (druppelen)"}, {"toegang", "access"}, {"omgeving", "environment, surroundings"}, {"weg te houden", "to keep away (weghouden)"}, {"macht", "power"}, {"binnenkort", "soon"}, {"mengsel", "mix, mixture"}, {"persoonlijk", "personally"}, {"onmogelijk", "impossible, insurmountable"} },
},

[5238] = { en = "Mission Accomplished!", tier = 4,
  t = "Missie geslaagd!",
  c = "$N, dat je de ketels hebt omgebouwd, is een enorme overwinning voor ons!$B$B<De high executor schraapt zijn keel en begint luid te brullen.>$B$BLaat iedereen hier het horen: voor dienst aan de Forsaken en aan de hele Horde, veel verder dan wat werd verwacht, tegen een grote overmacht en in ongelooflijk gevaar, mag ik wel zeggen, geef ik $N dit. En ik geef $Ghem:haar; onze eeuwige dankbaarheid als echte held van de Horde. Hoera!",
  g = { {"geslaagd", "accomplished, successful (slagen)"}, {"omgebouwd", "re-engineered, converted (ombouwen)"}, {"enorme", "tremendous, huge (enorm)"}, {"schraapt zijn keel", "clears his throat (keel schrapen)"}, {"brullen", "to bellow, to roar"}, {"overmacht", "overwhelming odds, superior force"}, {"ongelooflijk", "incredible"}, {"eeuwige", "eternal, undying (eeuwig)"}, {"dankbaarheid", "gratitude"}, {"hoera", "huzzah, hooray"} },
},

[105] = { en = "Alas, Andorhal", tier = 4,
  t = "Ach, Andorhal",
  d = "Ach, het moment is gekomen om Andorhal aan te vallen en de lich te verdrijven die de stad beheerst!$B$BIn de ruïnes van de stad heerst de lich: Araj the Summoner. Hij wordt bewaakt door talloze Scourge rond de resten van het stadscentrum, en zijn eigen lijfwacht van bewakers die direct bij hem horen is geducht. Je hebt veel bondgenoten nodig om zelfs maar een kans te maken tegen hem.$B$BVernietig Araj, $N, en breng me als bewijs een scherf van zijn fylacterium!",
  o = "Breng Araj's Phylactery Shard naar High Executor Derrington bij The Bulwark, Western Plaguelands.",
  p = "Je hebt je opdracht gekregen, $N. Heb je een scherf van het fylacterium van de lich, als bewijs dat de opdracht is uitgevoerd?",
  c = "Het is je gelukt! Araj... de lich is eindelijk verslagen!$B$BJe hebt de Horde vandaag een enorme dienst bewezen, $N. Je moed en doorzettingsvermogen laten zien wat het betekent om een echte held te zijn. Neem dit alsjeblieft aan, als teken voor iedereen dat jij de Horde een overwinning voor de geschiedenisboeken hebt gebracht!",
  g = { {"ach", "alas"}, {"verdrijven", "to drive out"}, {"beheerst", "controls (beheersen)"}, {"heerst", "rules, holds dominion (heersen)"}, {"talloze", "countless, numerous (talloos)"}, {"lijfwacht", "bodyguard, personal retinue"}, {"geducht", "formidable"}, {"scherf", "shard"}, {"fylacterium", "phylactery: the object holding a lich's soul"}, {"een dienst bewezen", "done a service (een dienst bewijzen)"}, {"doorzettingsvermogen", "perseverance"}, {"geschiedenisboeken", "history books (geschiedenisboek)"} },
},

[5342] = { en = "The Last Barov", tier = 4,
  t = "De laatste Barov",
  d = "Natuurlijk kan er, zolang mijn broer nog leeft, discussie ontstaan over wie de belangrijkste erfgenaam van het familiefortuin is. Dat kan niet.$B$BEen lage straatrat als jij is toch niet te goed voor een beetje koelbloedige moord, hoop ik.$B$BHet is een simpele taak, en ik verwacht dat je hem uitvoert. Tenminste, als je je beloning wilt hebben.$B$BWeldon zit onder bescherming van de Alliance in Chillwind Camp, in het oosten. Dood hem en breng zijn hoofd mee.$B$B<Alexi gaapt.>$B$BSchiet maar op nu.",
  o = "Reis naar Chillwind Camp, gebied van de Alliance, en vermoord Weldon Barov. Neem zijn hoofd mee en ga terug naar Alexi Barov.$B$BLet op: Weldon wordt waarschijnlijk goed beschermd door Alliance-tuig.",
  p = "Zorg dat mijn fortuin veilig is, en deel in de buit.",
  c = "Prachtig! Nu heb alleen ik de macht en het fortuin van huis Barov!$B$B<Alexi gooit een grote zak naar je toe.>$B$BEn hou het wisselgeld maar, smerig beest.",
  g = { {"discussie ontstaan", "contention arise (ontstaan)"}, {"erfgenaam", "heir, beneficiary"}, {"familiefortuin", "family fortune"}, {"straatrat", "guttersnipe, street rat"}, {"koelbloedige", "cold-blooded (koelbloedig)"}, {"gaapt", "yawns (gapen)"}, {"vermoord", "murder, assassinate (vermoorden)"}, {"tuig", "scum, riffraff"}, {"buit", "spoils, loot"}, {"wisselgeld", "change (money)"} },
},

[5511] = { en = "The Key to Scholomance", tier = 4,
  t = "De sleutel tot Scholomance",
  p = "Nou, hier is hij, $n: de voltooide Skeleton Key. Ik ben er zo zeker van als ik maar kan zijn dat je met deze sleutel binnen de muren van Scholomance kunt komen. Er is maar één manier om absoluut zeker te weten dat hij werkt. Verspil geen tijd en probeer hem uit, zou ik zeggen.",
  c = "Veel succes, machtige held. Mogen je overwinningen je roem en macht blijven brengen terwijl je Scholomance verwoest!",
  g = { {"voltooide", "completed (voltooien)"}, {"binnen de muren", "within the walls, within the confines"}, {"absoluut", "absolutely"}, {"verspil", "waste (verspillen)"}, {"roem", "fame"}, {"verwoest", "lay waste to, destroy (verwoesten)"} },
},

[5804] = { en = "Araj's Scarab", tier = 4,
  t = "Araj's Scarab",
  d = "Araj the Summoner heerst over Andorhal vanuit het hart van de verwoeste stad. We weten dat hij vroeger de leider van Scholomance was, voordat hij de stad voor zichzelf opeiste. Om de sleutel af te maken, hebben we zijn zegel nodig, een scarabee, als kop van de sleutel.$B$BGa naar het hart van Andorhal en breek zijn macht over de stad, nu hij naar buiten is gelokt. Als hij vernietigd is, pak je zijn scarabee van zijn gevallen fylacterium!$B$BDe sleutel tot Scholomance wacht op je, $N!",
  o = "Vernietig Araj the Summoner en breng Araj's Scarab naar Apothecary Dithers bij The Bulwark, Western Plaguelands.",
  p = "Je bent zo ver gekomen, $N. Alleen als het lichaam van Araj the Summoner wordt vernietigd, kunnen we de sleutel afmaken. Haal de scarabee van Araj, op welke manier dan ook, en breng hem naar mij. Ik maak hem vast als kop van de sleutel.",
  c = "Ja, dit is hem! Ik... ik sta weer helemaal versteld van je slimheid en moed. Het is gewoon niet te geloven hoe ver je wilt gaan om te winnen.$b$bLaat mij nu mijn kleine deel doen. Ik heb een speciaal oplosmiddel gemaakt waarmee ik de scarabee als kop op de sleutel kan vastzetten. Dat geeft de sleutel de kracht om door de gesloten deur van Scholomance te breken.$b$bDit duurt maar heel even...",
  g = { {"verwoeste", "ruined, destroyed (verwoest)"}, {"opeiste", "claimed (opeisen)"}, {"zegel", "signet, seal"}, {"scarabee", "scarab"}, {"gelokt", "drawn, lured (lokken)"}, {"fylacterium", "phylactery: the object holding a lich's soul"}, {"op welke manier dan ook", "by hook or by crook"}, {"sta versteld", "am amazed (versteld staan)"}, {"slimheid", "cunning, cleverness"}, {"oplosmiddel", "solvent"}, {"vastzetten", "to secure, to fix in place"} },
},

[5944] = { en = "In Dreams", tier = 4,
  t = "In dromen",
  d = "Zo lang ben ik een marionet geweest van de Grand Crusader. Waarom zou ik vechten tegen wat de Scarlet Crusade was geworden? Het is tientallen jaren geleden, maar de herinneringen aan mijn vader, die kostbare herinneringen, hebben me in leven gehouden.$B$BIk heb dromen, vreemdeling. In die dromen is mijn vader bij me. Hij staat trots naast me als ik word opgenomen in de Orde. We vechten zij aan zij tegen legioenen van de Scourge. We brengen eer aan de Alliance, aan Lordaeron.$B$BIk wil niet meer dromen.$B$BBreng me naar hem.",
  o = "Begeleid Taelan Fordring Hearthglen uit.",
  p = "<Tirion herstelt zich.>",
  c = "De dood van mijn zoon door toedoen van deze monsters zal niet zonder gevolgen blijven. Troost je met de gedachte dat de Orde opnieuw geboren is.$B$BIk neem nu mijn plaats in als Highlord van de nieuwe Order of the Silver Hand.$B$BDeze bezittingen uit mijn verleden zijn alles wat ik kan geven voor alles wat jij hebt gedaan. Neem ze alsjeblieft aan als teken van mijn dankbaarheid. Ze hebben me allemaal goed gediend door de jaren heen.$B$BMogen we elkaar weer ontmoeten, in betere tijden, en terugdenken aan lang vervlogen dagen... zwaar bevochten veldslagen... verloste dromen.",
  e = "Verlossing?",
  g = { {"marionet", "puppet"}, {"tientallen jaren", "decades"}, {"kostbare", "precious (kostbaar)"}, {"vreemdeling", "stranger"}, {"opgenomen", "inducted, admitted (opnemen)"}, {"zij aan zij", "side by side"}, {"legioenen", "legions (legioen)"}, {"begeleid", "escort (begeleiden)"}, {"herstelt zich", "regains his composure (zich herstellen)"}, {"door toedoen van", "at the hands of"}, {"gevolgen", "consequences (gevolg)"}, {"troost je", "take solace (zich troosten)"}, {"bezittingen", "possessions (bezitting)"}, {"lang vervlogen", "long past"}, {"verloste", "redeemed (verlossen)"}, {"verlossing", "redemption"} },
},

})

